    void zwp_confined_pointer_v1::init(struct ::wl_resource *resource)
    {
        m_resource = bind(resource);
    }

    zwp_confined_pointer_v1::Resource *zwp_confined_pointer_v1::add(struct ::wl_client *client, int version)
    {
        Resource *resource = bind(client, 0, version);
        m_resource_map.insert(client, resource);
        return resource;
    }

    zwp_confined_pointer_v1::Resource *zwp_confined_pointer_v1::add(struct ::wl_client *client, int id, int version)
    {
        Resource *resource = bind(client, id, version);
        m_resource_map.insert(client, resource);
        return resource;
    }

    zwp_confined_pointer_v1::Resource *zwp_confined_pointer_v1::add(struct ::wl_resource *resource)
    {
        return *m_resource_map.insert(wl_resource_get_client(resource), bind(resource));
    }

    void zwp_confined_pointer_v1::init(struct ::wl_display *display, int version)
    {
        m_display = display;
        m_global = wl_global_create(display, &::zwp_confined_pointer_v1_interface, version, this, bind_func);
        m_displayDestroyedListener.notify = zwp_confined_pointer_v1::display_destroy_func;
        m_displayDestroyedListener.parent = this;
#ifdef HAVE_ACK_GLOBAL_REMOVE
        wl_global_set_withdrawn_listener(m_global, [](wl_global *global) {
            auto object = static_cast<zwp_confined_pointer_v1 *>(wl_global_get_user_data(global));
            object->zwp_confined_pointer_v1_destroy_global();
        });
#endif
        wl_display_add_destroy_listener(display, &m_displayDestroyedListener);
    }

    const struct wl_interface *zwp_confined_pointer_v1::interface()
    {
        return &::zwp_confined_pointer_v1_interface;
    }

    zwp_confined_pointer_v1::Resource *zwp_confined_pointer_v1::zwp_confined_pointer_v1_allocate()
    {
        return new Resource;
    }

    void zwp_confined_pointer_v1::zwp_confined_pointer_v1_destroy_global()
    {
    }

    void zwp_confined_pointer_v1::zwp_confined_pointer_v1_bind_resource(Resource *)
    {
    }

    void zwp_confined_pointer_v1::zwp_confined_pointer_v1_destroy_resource(Resource *)
    {
    }

    void zwp_confined_pointer_v1::bind_func(struct ::wl_client *client, void *data, uint32_t version, uint32_t id)
    {
        zwp_confined_pointer_v1 *that = static_cast<zwp_confined_pointer_v1 *>(data);
        that->add(client, id, version);
    }

    void zwp_confined_pointer_v1::display_destroy_func(struct ::wl_listener *listener, void *data)
    {
        Q_UNUSED(data);
        zwp_confined_pointer_v1 *that = static_cast<zwp_confined_pointer_v1::DisplayDestroyedListener *>(listener)->parent;
        that->m_global = nullptr;
        that->m_globalRemovedEvent = nullptr;
    }

    void zwp_confined_pointer_v1::destroy_func(struct ::wl_resource *client_resource)
    {
        Resource *resource = Resource::fromResource(client_resource);
        Q_ASSERT(resource);
        zwp_confined_pointer_v1 *that = resource->zwp_confined_pointer_v1_object;
        if (Q_LIKELY(that)) {
            that->m_resource_map.remove(resource->client(), resource);
            that->zwp_confined_pointer_v1_destroy_resource(resource);

            that = resource->zwp_confined_pointer_v1_object;
            if (that && that->m_resource == resource)
                that->m_resource = nullptr;
        }
        delete resource;
    }


    void zwp_confined_pointer_v1::globalRemove()
    {
        if (!m_global || m_globalRemovedEvent)
            return;

        struct wl_event_loop *event_loop = wl_display_get_event_loop(m_display);
        m_globalRemovedEvent = wl_event_loop_add_timer(event_loop, deferred_destroy_global_func, this);
        wl_event_source_timer_update(m_globalRemovedEvent, 24 * 60 * 60 * 1000);

        wl_global_remove(m_global);
    }

    zwp_confined_pointer_v1::Resource *zwp_confined_pointer_v1::bind(struct ::wl_client *client, uint32_t id, int version)
    {
        Q_ASSERT_X(!wl_client_get_object(client, id), "QWaylandObject bind", QStringLiteral("binding to object %1 more than once").arg(id).toLocal8Bit().constData());
        struct ::wl_resource *handle = wl_resource_create(client, &::zwp_confined_pointer_v1_interface, version, id);
        return bind(handle);
    }

    zwp_confined_pointer_v1::Resource *zwp_confined_pointer_v1::bind(struct ::wl_resource *handle)
    {
        Resource *resource = zwp_confined_pointer_v1_allocate();
        resource->zwp_confined_pointer_v1_object = this;

        wl_resource_set_implementation(handle, &m_zwp_confined_pointer_v1_interface, resource, destroy_func);
        resource->handle = handle;
        zwp_confined_pointer_v1_bind_resource(resource);
        return resource;
    }
    zwp_confined_pointer_v1::Resource *zwp_confined_pointer_v1::Resource::fromResource(struct ::wl_resource *resource)
    {
        if (Q_UNLIKELY(!resource))
            return nullptr;
        if (wl_resource_instance_of(resource, &::zwp_confined_pointer_v1_interface, &m_zwp_confined_pointer_v1_interface))
            return static_cast<Resource *>(wl_resource_get_user_data(resource));
        return nullptr;
    }

    const struct ::zwp_confined_pointer_v1_interface zwp_confined_pointer_v1::m_zwp_confined_pointer_v1_interface = {
        zwp_confined_pointer_v1::handle_destroy,
        zwp_confined_pointer_v1::handle_set_region
    };

    void zwp_confined_pointer_v1::zwp_confined_pointer_v1_destroy(Resource *)
    {
    }

    void zwp_confined_pointer_v1::zwp_confined_pointer_v1_set_region(Resource *, struct ::wl_resource *)
    {
    }


    void zwp_confined_pointer_v1::handle_destroy(
        ::wl_client *client,
        struct wl_resource *resource)
    {
        Q_UNUSED(client);
        Resource *qtResource = Resource::fromResource(resource);
        if (Q_UNLIKELY(!qtResource->zwp_confined_pointer_v1_object)) {
            wl_resource_destroy(resource);
            return;
        }
        static_cast<zwp_confined_pointer_v1 *>(qtResource->zwp_confined_pointer_v1_object)->zwp_confined_pointer_v1_destroy(
            qtResource);
    }

    void zwp_confined_pointer_v1::handle_set_region(
        ::wl_client *client,
        struct wl_resource *resource,
        struct ::wl_resource *region)
    {
        Q_UNUSED(client);
        Resource *qtResource = Resource::fromResource(resource);
        if (Q_UNLIKELY(!qtResource->zwp_confined_pointer_v1_object)) {
            return;
        }
        static_cast<zwp_confined_pointer_v1 *>(qtResource->zwp_confined_pointer_v1_object)->zwp_confined_pointer_v1_set_region(
            qtResource,
            region);
    }

    void zwp_confined_pointer_v1::send_confined()
    {
        Q_ASSERT_X(m_resource, "zwp_confined_pointer_v1::confined", "Uninitialised resource");
        if (Q_UNLIKELY(!m_resource)) {
            qWarning("could not call zwp_confined_pointer_v1::confined as it's not initialised");
            return;
        }
        send_confined(
            m_resource->handle);
    }

    void zwp_confined_pointer_v1::send_confined(struct ::wl_resource *resource)
    {
        zwp_confined_pointer_v1_send_confined(
            resource);
    }


    void zwp_confined_pointer_v1::send_unconfined()
    {
        Q_ASSERT_X(m_resource, "zwp_confined_pointer_v1::unconfined", "Uninitialised resource");
        if (Q_UNLIKELY(!m_resource)) {
            qWarning("could not call zwp_confined_pointer_v1::unconfined as it's not initialised");
            return;
        }
        send_unconfined(
            m_resource->handle);
    }

    void zwp_confined_pointer_v1::send_unconfined(struct ::wl_resource *resource)
    {
        zwp_confined_pointer_v1_send_unconfined(
            resource);
    }

